pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title TicTacToe
 * @notice A gas-optimized, secure, non-custodial PvP Tic Tac Toe game.
 * @dev Implements Pull-over-Push payments, packed storage, and game timeouts.
 */
contract TicTacToe is ReentrancyGuard {
    // ═══════════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════════

    error InvalidStake(uint256 sent, uint256 required);
    error GameNotJoinable();
    error GameNotActive();
    error NotYourTurn();
    error NotPlayer();
    error CellOccupied();
    error InvalidMove();
    error GameNotExpired();
    error NothingToWithdraw();
    error TransferFailed();
    error NoTreasuryBalance();

    // ═══════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════

    event GameCreated(uint256 indexed gameId, address indexed player1, uint256 stake);
    event GameJoined(uint256 indexed gameId, address indexed player2);
    event MoveMade(uint256 indexed gameId, address indexed player, uint8 cellIndex);
    event GameFinished(uint256 indexed gameId, address indexed winner, uint256 prize);
    event GameDraw(uint256 indexed gameId);
    event Withdrawal(address indexed player, uint256 amount);
    event TreasuryFunded(address indexed sender, uint256 amount);

    // ═══════════════════════════════════════════════════════════════
    // CONSTANTS & IMMUTABLES
    // ═══════════════════════════════════════════════════════════════

    uint256 public constant PROTOCOL_FEE_BPS = 250; // 2.5%
    uint256 public constant TIMEOUT_DURATION = 1 hours;
    uint8 private constant CELL_EMPTY = 0;
    uint8 private constant CELL_X = 1; // Player 1
    uint8 private constant CELL_O = 2; // Player 2

    // Using immutable for owner to save gas on reads (set in constructor)
    address public immutable owner;

    // ═══════════════════════════════════════════════════════════════
    // STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════

    enum GameState { WAITING, ACTIVE, FINISHED }

    struct Game {
        // Slot 0 (32 bytes)
        address player1;      // 20 bytes
        uint32 lastMoveTime;  // 4 bytes
        uint16 board;         // 2 bytes (9 cells * 2 bits = 18 bits)
        uint8 movesCount;     // 1 byte
        GameState state;      // 1 byte (enum stored as uint8)
        // Slot 1 (32 bytes)
        address player2;      // 20 bytes
        uint96 stake;         // 12 bytes (Max ~79 billion ETH, plenty)
    }

    /// @notice Stores all game sessions
    mapping(uint256 => Game) public games;

    /// @notice Pending winnings/withdrawals for users (Pull-over-Push)
    mapping(address => uint256) public pendingWithdrawals;

    /// @notice Accumulated protocol fees
    uint256 public accumulatedFees;

    /// @notice Total number of games created
    uint256 public gameIdCounter;

    // ═══════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    constructor() {
        owner = msg.sender;
    }

    receive() external payable {
        emit TreasuryFunded(msg.sender, msg.value);
    }

    // ═══════════════════════════════════════════════════════════════
    // EXTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Create a new game with a wager.
     * @return gameId The ID of the created game.
     */
    function createGame() external payable returns (uint256 gameId) {
        unchecked {
            gameId = ++gameIdCounter;
        }

        // Initialize game struct
        // Uses explicit casting to fit packed slots
        games[gameId] = Game({
            player1: msg.sender,
            lastMoveTime: uint32(block.timestamp),
            board: 0,
            movesCount: 0,
            state: GameState.WAITING,
            player2: address(0),
            stake: uint96(msg.value)
        });

        emit GameCreated(gameId, msg.sender, msg.value);
    }

    /**
     * @notice Join an existing game. Must match the stake.
     * @param _gameId The ID of the game to join.
     */
    function joinGame(uint256 _gameId) external payable {
        Game storage g = games[_gameId];

        if (g.state != GameState.WAITING) revert GameNotJoinable();
        if (msg.value != uint256(g.stake)) revert InvalidStake(msg.value, g.stake);
        if (g.player1 == msg.sender) revert GameNotJoinable(); // Cannot play against self

        // State update
        g.player2 = msg.sender;
        g.state = GameState.ACTIVE;
        g.lastMoveTime = uint32(block.timestamp);

        emit GameJoined(_gameId, msg.sender);
    }

    /**
     * @notice Make a move on the board.
     * @param _gameId The ID of the game.
     * @param _cellIndex The index of the cell (0-8) starting top-left.
     */
    function makeMove(uint256 _gameId, uint8 _cellIndex) external nonReentrant {
        if (_cellIndex > 8) revert InvalidMove();

        // Cache storage to memory for gas savings
        Game storage g = games[_gameId];
        // Read critical packed values once
        address p1 = g.player1;
        address p2 = g.player2;
        GameState currentState = g.state;
        uint8 moves = g.movesCount;
        uint16 currentBoard = g.board;
        uint32 lastTime = g.lastMoveTime;

        // 1. Validations
        if (currentState != GameState.ACTIVE) revert GameNotActive();

        // Check timeout first - if previous player took too long, they shouldn't be able to move
        // However, standard logic is: explicit timeout claim required. 
        // Here we just enforce it's the right player.

        bool isP1Turn = (moves % 2 == 0);
        address expectedPlayer = isP1Turn ? p1 : p2;

        if (msg.sender != expectedPlayer) revert NotYourTurn();

        // Check cell emptiness using bitwise op
        // Each cell is 2 bits. Shift = cellIndex * 2. Mask = 11 (binary) = 3.
        uint256 shift = _cellIndex * 2;
        if ((currentBoard >> shift) & 3 != CELL_EMPTY) revert CellOccupied();

        // 2. Effects

        // Update Board
        uint8 playerSymbol = isP1Turn ? CELL_X : CELL_O;
        uint16 newBoard = currentBoard | (uint16(playerSymbol) << shift);

        g.board = newBoard;
        g.lastMoveTime = uint32(block.timestamp);

        // Increment moves using unchecked (max 9)
        unchecked {
            ++moves;
        }
        g.movesCount = moves;

        emit MoveMade(_gameId, msg.sender, _cellIndex);

        // 3. Win/Draw Condition Check
        if (_checkWin(newBoard, playerSymbol)) {
            _endGame(_gameId, g, msg.sender);
        } else if (moves == 9) {
            _drawGame(_gameId, g);
        }
    }

    /**
     * @notice Claim victory if opponent hasn't moved in time.
     * @param _gameId The ID of the game.
     */
    function claimTimeout(uint256 _gameId) external nonReentrant {
        Game storage g = games[_gameId];

        if (g.state != GameState.ACTIVE) revert GameNotActive();

        // Check if timeout duration passed
        unchecked {
            if (block.timestamp <= uint256(g.lastMoveTime) + TIMEOUT_DURATION) {
                revert GameNotExpired();
            }
        }

        // Determine who timed out.
        // If moves % 2 == 0, it's P1's turn. If they didn't move, P2 wins.
        bool isP1Turn = (g.movesCount % 2 == 0);
        address winner = isP1Turn ? g.player2 : g.player1;

        // Only the winner can claim (prevents griefing from 3rd parties)
        if (msg.sender != winner) revert NotPlayer();

        // Finalize
        _endGame(_gameId, g, winner);
    }

    /**
     * @notice Withdraw accumulated winnings.
     */
    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        if (amount == 0) revert NothingToWithdraw();

        // CEI: Effects before interactions
        pendingWithdrawals[msg.sender] = 0;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Withdrawal(msg.sender, amount);
    }

    /**
     * @notice Admin function to withdraw accumulated protocol fees.
     */
    function withdrawTreasury() external nonReentrant {
        if (msg.sender != owner) revert TransferFailed(); // Reusing error for auth failure to save code size

        uint256 amount = accumulatedFees;
        if (amount == 0) revert NoTreasuryBalance();

        accumulatedFees = 0;

        (bool success, ) = payable(owner).call{value: amount}("");
        if (!success) revert TransferFailed();
    }

    // ═══════════════════════════════════════════════════════════════
    // INTERNAL LOGIC
    // ═══════════════════════════════════════════════════════════════

    /**
     * @dev Handles game completion with a winner.
     */
    function _endGame(uint256 _gameId, Game storage _g, address _winner) internal {
        _g.state = GameState.FINISHED;

        uint256 totalPot = uint256(_g.stake) * 2;

        // Calculate fee
        uint256 fee = (totalPot * PROTOCOL_FEE_BPS) / 10000;
        uint256 prize = totalPot - fee;

        // Update balances (Pull-over-Push)
        if (fee > 0) {
            accumulatedFees += fee;
        }
        pendingWithdrawals[_winner] += prize;

        emit GameFinished(_gameId, _winner, prize);
    }

    /**
     * @dev Handles game draw (refunds stakes).
     */
    function _drawGame(uint256 _gameId, Game storage _g) internal {
        _g.state = GameState.FINISHED;

        uint256 stake = uint256(_g.stake);

        // Refund exact stakes, no fees on draw
        pendingWithdrawals[_g.player1] += stake;
        pendingWithdrawals[_g.player2] += stake;

        emit GameDraw(_gameId);
    }

    /**
     * @dev Checks bitwise board for winning patterns.
     * @param board The packed uint16 board representation.
     * @param p The player symbol (1 for X, 2 for O).
     */
    function _checkWin(uint16 board, uint8 p) internal pure returns (bool) {
        // Winning masks (pre-calculated for gas).
        // A row is won if all 3 cells equal p.
        // We iterate through 8 possible winning lines.

        // Lines represented as array of 3 indices [c1, c2, c3]
        // 0,1,2 (Row 1), 3,4,5 (Row 2), 6,7,8 (Row 3)
        // 0,3,6 (Col 1), 1,4,7 (Col 2), 2,5,8 (Col 3)
        // 0,4,8 (Diag 1), 2,4,6 (Diag 2)

        // Since we can't easily loop over arrays in memory without alloc cost,
        // we unroll the checks slightly or use a packed verify helper.

        return 
            _isLine(board, 0, 1, 2, p) ||
            _isLine(board, 3, 4, 5, p) ||
            _isLine(board, 6, 7, 8, p) ||
            _isLine(board, 0, 3, 6, p) ||
            _isLine(board, 1, 4, 7, p) ||
            _isLine(board, 2, 5, 8, p) ||
            _isLine(board, 0, 4, 8, p) ||
            _isLine(board, 2, 4, 6, p);
    }

    /**
     * @dev Helper to check if 3 cells match the player symbol.
     */
    function _isLine(uint16 board, uint8 c1, uint8 c2, uint8 c3, uint8 p) private pure returns (bool) {
        // Extract values using bit shifts
        // Mask 3 (binary 11) gets the 2 bits
        uint256 v1 = (board >> (c1 * 2)) & 3;
        uint256 v2 = (board >> (c2 * 2)) & 3;
        uint256 v3 = (board >> (c3 * 2)) & 3;

        return (v1 == p && v2 == p && v3 == p);
    }

    // ═══════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Get board state unpacked.
     * @param _gameId Game ID.
     * @return boardArray 9-length array of cell values (0, 1, 2).
     */
    function getBoard(uint256 _gameId) external view returns (uint8[9] memory boardArray) {
        uint16 packed = games[_gameId].board;
        for (uint8 i = 0; i < 9;) {
            boardArray[i] = uint8((packed >> (i * 2)) & 3);
            unchecked { ++i; }
        }
    }
}

